/* Every rig rotates around (0, 0), the exact contact point on the rope. */
window.initShadesHero=function(){
 const original=document.querySelector('.hero');if(!original)return;
 const chevron=direction=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${direction==='left'?'m14 6-6 6 6 6':'m10 6 6 6-6 6'}"/></svg>`;
 original.outerHTML=`<section class="atelier-hero" aria-label="SHADES Atelier collection"><div class="atelier-intro"><span class="eyebrow">THE ATELIER COLLECTION</span><h1>Silhouettes that <em>hang right.</em></h1><p>Considered shirts. Effortless trousers. A different shade of you.</p><div class="atelier-tabs" aria-label="Choose clothing rail"><button data-rail="Shirts" aria-pressed="true">Shirts <span>07</span></button><button data-rail="Trousers" aria-pressed="false">Trousers <span>07</span></button></div></div><div class="atelier-scene" id="atelier-scene" tabindex="0" role="region" aria-label="Clothing rail. Drag to browse, tap or hover to select, or use the left and right arrow keys." aria-describedby="atelier-help"><div class="atelier-camera"><svg class="atelier-rope" aria-hidden="true"><defs><linearGradient id="rope-finish" x2="0" y2="1"><stop stop-color="#b9ad92"/><stop offset=".5" stop-color="#d2c8b4"/><stop offset="1" stop-color="#958b74"/></linearGradient></defs><path id="rope-shadow"/><path id="rope-line"/></svg><div id="atelier-rack"></div><div class="atelier-spot" aria-hidden="true"></div></div></div><div class="atelier-footer"><div class="atelier-help"><p id="atelier-help">Hover a piece — click to look closer.</p><a href="shop.html" class="text-link">Explore collection</a></div><div class="atelier-details" id="atelier-details" aria-live="polite"></div><div class="atelier-controls"><button id="atelier-prev" aria-label="Previous garment">${chevron('left')}</button><span id="atelier-count"></span><button id="atelier-next" aria-label="Next garment">${chevron('right')}</button></div></div></section>`;
 const hero=document.querySelector('.atelier-hero'),scene=document.querySelector('#atelier-scene'),rack=document.querySelector('#atelier-rack'),panel=document.querySelector('#atelier-details'),rope=document.querySelector('#rope-line'),ropeShadow=document.querySelector('#rope-shadow'),svg=document.querySelector('.atelier-rope');
 const reduced=matchMedia('(prefers-reduced-motion: reduce)');let category='Shirts',pieces=[],nodes=[],states=[],active=-1,position=0,target=0,velocity=0,frameId=0,previousTime=0,drag=null,view='front',suppressedClick=false,visible=true;
 let showroom=null;const motion={pan:0,phase:0};
 const touchRail=matchMedia('(hover: none), (max-width: 760px)');const updateHelp=()=>document.querySelector('#atelier-help').textContent=touchRail.matches?'Swipe the rail — tap a piece to look closer.':'Hover a piece — click to look closer.';updateHelp();touchRail.addEventListener('change',updateHelp);
 const wrap=n=>((n%7)+7)%7;
 function hanger(p){const pants=p.category==='Trousers';return `<svg class="rig-hanger" viewBox="-120 -12 240 132" aria-hidden="true"><path class="hanger-hook" d="M0 34V21C0 14 11 14 11 6C11-2 3-5-3-2C-7 0-8 4-6 7"/>${pants?'<path class="hanger-stem" d="M0 34V48"/><rect class="trouser-bar" x="-64" y="47" width="128" height="7" rx="2"/><path class="trouser-clip" d="M-52 52v15m104-15v15"/>':'<path class="wood-hanger" d="M0 34L-65 62Q-69 65-64 66H64Q69 65 65 62L0 34Z"/><path class="hanger-grain" d="M-60 63H60"/>'}</svg>`}
 function garment(p){return `<span class="rig-garment"><span class="turn-face turn-front"><img src="${p.views.front}" alt="${p.name}, front view" width="640" height="1040" decoding="async"></span><span class="turn-face turn-side"><img src="${p.views.side}" alt="${p.name}, side view" width="640" height="1040" decoding="async"></span><span class="turn-face turn-back"><img src="${p.views.back}" alt="${p.name}, back view" width="640" height="1040" decoding="async"></span></span>`}
 function setDetails(index){const changed=index!==active;active=index;if(changed)view='front';const p=pieces[index];nodes.forEach((node,i)=>{node.classList.toggle('chosen',i===index);node.setAttribute('aria-pressed',String(i===index));node.tabIndex=i===index?0:-1});document.querySelector('#atelier-count').textContent=String(index+1).padStart(2,'0')+' / 07';panel.innerHTML=`<div class="atelier-piece-title"><h2>${p.name}</h2><span>${money(p.price)}</span></div><p class="atelier-piece-info"><span class="atelier-swatch" style="background:${p.swatch}"></span>${p.color} · ${p.fabric} · ${p.fit} fit</p><div class="atelier-piece-actions"><div class="atelier-views" aria-label="View garment angle">${['front','side','back'].map(v=>`<button data-angle="${v}" aria-pressed="${view===v}">${v[0].toUpperCase()+v.slice(1)}</button>`).join('')}</div><button type="button" id="atelier-open" class="button dark">Look closer</button></div>`;panel.querySelectorAll('[data-angle]').forEach(b=>b.onclick=()=>{view=b.dataset.angle;panel.querySelectorAll('[data-angle]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));wake()});panel.querySelector('#atelier-open').onclick=()=>showroom?showroom.open(p,nodes[index]):location.assign(url(p));wake();}
 function select(index){if(index===active)return;setDetails(index);states[index].swingVelocity+=.05;wake()}
 function build(nextCategory){category=nextCategory;pieces=P.filter(p=>p.category===category);position=target=0;velocity=0;active=-1;states=pieces.map(()=>({angle:72,angularVelocity:0,scale:1,scaleVelocity:0,swing:0,swingVelocity:0}));rack.innerHTML=pieces.map((p,i)=>`<button class="atelier-piece ${category==='Trousers'?'is-trouser':''}" data-piece="${i}" aria-label="Select ${p.name}" aria-pressed="false"><span class="atelier-price-tag" aria-hidden="true">${money(p.price)}</span><span class="hanger-rig">${hanger(p)}${garment(p)}</span></button>`).join('');nodes=[...rack.children];nodes.forEach((node,i)=>{node.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse'&&!drag&&Math.abs(position-target)<.01)select(i)});node.onclick=()=>{if(!suppressedClick){select(i);showroom?.open(pieces[i],node)}};node.onfocus=()=>select(i)});setDetails(0);paint();wake();}
 function spacing(){return Math.min(186,Math.max(139,scene.clientWidth/7.5))}
 function railY(x,width){return 54+44*(1-Math.pow(2*x/width-1,2))}
 function paint(){const width=scene.clientWidth,height=scene.clientHeight,step=spacing(),bodyHeight=Math.min(category==='Trousers'?395:370,height-165),bodyWidth=bodyHeight*640/1040;svg.setAttribute('viewBox',`0 0 ${width} ${height}`);const path=`M0 54 Q${width/2} 142 ${width} 54`;rope.setAttribute('d',path);ropeShadow.setAttribute('d',path);nodes.forEach((node,i)=>{let d=wrap(i-position+3)-3;const x=width/2+d*step+motion.pan,y=railY(x,width),s=states[i];node.style.left=x+'px';node.style.top=y+'px';node.style.setProperty('--garment-h',bodyHeight+'px');node.style.setProperty('--garment-w',bodyWidth+'px');node.style.zIndex=i===active?'10':String(7-Math.round(Math.abs(d)));node.style.opacity=i===active?'1':'.86';node.style.visibility=Math.abs(d*step)>width/2+150?'hidden':'visible';const radians=s.angle*Math.PI/180,cos=Math.cos(radians),sin=Math.sin(radians),fw=Math.pow(Math.max(0,cos),4),bw=Math.pow(Math.max(0,-cos),4),sw=sin*sin,total=fw+bw+sw||1;node.querySelector('.turn-front').style.opacity=fw/total;node.querySelector('.turn-side').style.opacity=sw/total;node.querySelector('.turn-back').style.opacity=bw/total;node.querySelector('.hanger-rig').style.transform=`rotateY(${s.angle}deg) rotateZ(${s.swing+(reduced.matches?0:Math.sin(motion.phase+i*.75)*.18)}deg) scale(${s.scale})`;});}
 function spring(state,key,velocityKey,goal,dt,stiffness=160,damping=26){const force=(goal-state[key])*stiffness-state[velocityKey]*damping;state[velocityKey]+=force*dt;state[key]+=state[velocityKey]*dt;const moving=Math.abs(goal-state[key])>.005||Math.abs(state[velocityKey])>.01;if(!moving){state[key]=goal;state[velocityKey]=0}return moving}
 function animate(time){frameId=0;const dt=previousTime?Math.min((time-previousTime)/1000,.025):1/60;previousTime=time;let moving=false;if(reduced.matches){position=target;velocity=0}else{velocity+=((target-position)*120-velocity*23)*dt;position+=velocity*dt;if(Math.abs(position-target)<.0001&&Math.abs(velocity)<.001){position=target;velocity=0}else moving=true}states.forEach((s,i)=>{const goal=i===active?(view==='back'?180:view==='side'?90:0):72;if(reduced.matches){s.angle=goal;s.scale=i===active?1.035:1;s.swing=0}else{moving=spring(s,'angle','angularVelocity',goal,dt)||moving;moving=spring(s,'scale','scaleVelocity',i===active?1.035:1,dt)||moving;moving=spring(s,'swing','swingVelocity',0,dt,85,16)||moving}});paint();if(moving&&visible)frameId=requestAnimationFrame(animate);else previousTime=0;}
 function wake(){if(!frameId&&visible)frameId=requestAnimationFrame(animate)}
 function step(direction){target=Math.round(target)+direction;select(wrap(Math.round(target)));wake()}
 document.querySelectorAll('[data-rail]').forEach(b=>b.onclick=()=>{if(category===b.dataset.rail)return;document.querySelectorAll('[data-rail]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));build(b.dataset.rail)});
 document.querySelector('#atelier-prev').onclick=()=>step(-1);document.querySelector('#atelier-next').onclick=()=>step(1);
 scene.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();if(e.key==='Home'){target=0;select(0)}else if(e.key==='End'){target=6;select(6)}else step(e.key==='ArrowRight'?1:-1);wake()}});
 scene.addEventListener('pointerdown',e=>{if(e.button!==0)return;if(e.pointerType==='mouse')e.preventDefault();drag={id:e.pointerId,x:e.clientX,start:position,moved:0};target=position;velocity=0;suppressedClick=false});
 scene.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;const dx=e.clientX-drag.x;drag.moved=Math.max(drag.moved,Math.abs(dx));if(drag.moved>6){scene.setPointerCapture(e.pointerId);hero.classList.add('dragging');suppressedClick=true;position=target=drag.start-dx/spacing();states.forEach(s=>{s.swing=Math.max(-.8,Math.min(.8,dx*.0015))});paint()}});
 function release(e){if(!drag||e.pointerId!==drag.id)return;const didDrag=drag.moved>6;drag=null;hero.classList.remove('dragging');if(didDrag){target=Math.round(target);select(wrap(target));wake()}setTimeout(()=>suppressedClick=false,0)}
 window.addEventListener('pointerup',release);scene.addEventListener('pointercancel',release);scene.addEventListener('lostpointercapture',release);
 new ResizeObserver(()=>{paint();wake()}).observe(scene);new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;showroom?.visibility(visible);if(visible)wake()}).observe(hero);reduced.addEventListener('change',wake);build('Shirts');showroom=window.initShowroom?.({hero,scene,camera:hero.querySelector('.atelier-camera'),motion,paint});
 const warmImages=()=>P.forEach(p=>Object.values(p.views).forEach(src=>{const image=new Image();image.decoding='async';image.src=src}));if('requestIdleCallback' in window)requestIdleCallback(warmImages,{timeout:2000});else setTimeout(warmImages,1000);
};
